//! Synthetic dispatch follows genuine inert parent edges and native identities.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=main>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://inert-event.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var owner=new Document(),root=owner.createElement('Root'),parent=owner.createElement('Parent'),leaf=owner.createElement('Leaf');owner.appendChild(root);root.appendChild(parent);parent.appendChild(leaf);var calls=0,e=new CustomEvent('check',{bubbles:true,cancelable:true,composed:true,detail:{held:leaf}}),dispatch=EventTarget.prototype.dispatchEvent;");(d,f,p)}
#[test]
fn event_inert_paths_xml_capture_target_bubble_cancellation_and_actual_path(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var expected=[leaf,parent,root,owner],log='',outside=0;window.addEventListener('check',function(){outside++;});document.addEventListener('check',function(){outside++;});function check(event){var path=event.composedPath();if(path.length!==4||event.target!==leaf||event.srcElement!==leaf||event.detail.held!==leaf||event.isTrusted)throw 'actual inert event fields';for(var i=0;i<4;i++)if(path[i]!==expected[i])throw 'actual inert path identity';path[0]=window;if(event.composedPath()[0]!==leaf)throw 'independent path array';}function listen(node,tag,capture){node.addEventListener('check',function(event){check(event);if(event.currentTarget!==node)throw 'actual inert current target';log+=tag+event.eventPhase;},capture);}listen(owner,'D',true);listen(root,'R',true);listen(parent,'P',true);listen(leaf,'L',true);listen(leaf,'L',false);listen(parent,'P',false);listen(root,'R',false);listen(owner,'D',false);parent.addEventListener('check',function(event){event.preventDefault();if(event.defaultPrevented)throw 'passive cancellation';},{capture:true,passive:true});leaf.addEventListener('check',function(event){event.preventDefault();});if(dispatch.call(leaf,e)!==false||log!=='D1R1P1L2L2P3R3D3'||outside||!e.defaultPrevented||e.currentTarget!==null||e.eventPhase!==0||e.target!==leaf||e.composedPath().length)throw 'real inert propagation cancellation and cleanup';
"#);assert!(p.state.synthetic_dispatches.is_empty());assert!(p.state.created_events.iter().all(|e|!e.dispatching));}
#[test]
fn event_inert_paths_parsed_template_root_does_not_cross_host_or_owner_document(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var parsed=new DOMParser().parseFromString('<body><template id=t><div><b>X</b></div></template></body>','text/html'),host=parsed.getElementById('t'),fragment=host.content,branch=fragment.firstChild,target=branch.firstChild,seen='',outside=0;for(var node of [host,parsed,fragment.ownerDocument,window,document])node.addEventListener('inside',function(){outside++;});fragment.addEventListener('inside',function(event){var path=event.composedPath();if(path.length!==3||path[0]!==target||path[1]!==branch||path[2]!==fragment||event.eventPhase!==1)throw 'native template fragment root path';seen+='c';},true);branch.addEventListener('inside',function(event){if(event.currentTarget!==branch||event.eventPhase!==3)throw 'parsed inert parent bubble';seen+='b';});target.addEventListener('inside',function(){seen+='t';});if(!target.dispatchEvent(new Event('inside',{bubbles:true,composed:true}))||seen!=='ctb'||outside)throw 'actual inert fragment path without host or Window bridge';
"#);}
#[test]
fn event_inert_paths_native_document_fragment_character_kinds_and_wrapped_listener_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var targets=[owner,owner.createDocumentFragment(),owner.createTextNode('X'),owner.createComment('X'),owner.createCDATASection('X'),owner.createProcessingInstruction('target','X')];for(var target of targets){var hits=0;target.addEventListener('alone',function(event){var path=event.composedPath();if(event.target!==target||event.currentTarget!==target||event.eventPhase!==2||path.length!==1||path[0]!==target)throw 'actual root or CharacterData target';hits++;});if(!target.dispatchEvent(new Event('alone',{bubbles:true}))||hits!==1)throw 'genuine native root dispatch';}var text=owner.createTextNode('A😀B'),wrapper=owner.createElement('Wrapper'),saved={};wrapper.author=saved;wrapper.addEventListener('wrapped',function(event){if(event.target!==wrapper||this!==wrapper||this.author!==saved||this.parentNode!==parent)throw 'actual generic wrapper listener identity';calls++;});parent.appendChild(text);var range=owner.createRange();range.setStart(text,1);range.setEnd(text,3);range.surroundContents(wrapper);wrapper.dispatchEvent(new Event('wrapped'));if(calls!==1||wrapper.textContent!=='😀'||wrapper.ownerDocument!==owner)throw 'native generic wrapper consumer dispatch';
"#);}
#[test]
fn event_inert_paths_current_dispatch_retains_path_across_native_reparenting(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var other=owner.createElement('Other');root.appendChild(other);var seen='',expected=parent,mutations=new MutationObserver(function(){throw 'drained';});mutations.observe(root,{subtree:true,childList:true});owner.addEventListener('check',function(event){other.appendChild(leaf);if(event.composedPath()[1]!==parent||leaf.parentNode!==other)throw 'snapshot path after native reparent';},{capture:true,once:true});parent.addEventListener('check',function(event){if(event.currentTarget!==expected||event.composedPath()[1]!==expected)throw 'original ancestor remains in active path';seen+='p';});other.addEventListener('check',function(event){if(event.composedPath()[1]!==other)throw 'new dispatch resolves current parent';seen+='o';});leaf.dispatchEvent(e);if(seen!=='p'||leaf.parentNode!==other||mutations.takeRecords().length!==2)throw 'original path and real move observations';expected=other;leaf.dispatchEvent(e);if(seen!=='po'||e.currentTarget!==null||e.composedPath().length)throw 'fresh dispatch uses actual new path';
"#);}
#[test]
fn event_inert_paths_resource_and_captured_method_authority_refusal_cleanup_and_recovery(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"root.addEventListener('check',function(event){if(event.composedPath()[2]!==root)throw 'real recovery path';calls++;});");let before=(p.state.retained,p.state.dom_commits);let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>{p.state.host_work=4096;p.state.execution_deadline=Some(Instant::now());}}assert!(p.runtime.execute("dispatch.call(leaf,e)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.retained,p.state.dom_commits),before);assert!(p.state.synthetic_dispatches.is_empty());assert!(p.state.created_events.iter().all(|e|!e.dispatching));p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(calls||e.currentTarget!==null||e.eventPhase||e.composedPath().length)throw 'dispatch refusal has no callback prefix';if(!dispatch.call(leaf,e)||calls!==1)throw 'fresh genuine inert dispatch recovery';");}
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var foreignDispatch=frame.contentWindow.EventTarget.prototype.dispatchEvent,boundDispatch=foreignDispatch.bind(leaf);leaf.addEventListener('check',function(){calls++;});");let before=(p.state.retained,p.state.dom_commits);p.set_location(&crate::navigation::address("https://foreign.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();for source in ["foreignDispatch.call(leaf,e)","foreignDispatch.call(document.getElementById('main'),e)","boundDispatch(e)"]{p.begin_job();let error=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!((p.state.retained,p.state.dom_commits),before);}assert!(p.state.synthetic_dispatches.is_empty());p.set_location(&crate::navigation::address("https://inert-event.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(calls)throw 'captured origin refusal';foreignDispatch.call(leaf,e);if(calls!==1||e.isTrusted||e.currentTarget!==null||e.composedPath().length)throw 'captured method native origin recovery';");
}
